const items=$input.all();
const syn=$('Get Syntheses').all();
const sh=syn.filter(s=>s.json.round_number&&s.json.synthesis_text).sort((a,b)=>(a.json.round_number||0)-(b.json.round_number||0)).map(s=>'RUNDE '+s.json.round_number+' (Synthese):\n'+s.json.synthesis_text).join('\n\n---\n\n');
const first=items[0];
if(!first||!first.json||Object.keys(first.json).length===0){
  return [{json:{name:null,profile:null,session_id:null,persona_id:null,slack_slot:null,synthesis_history:sh,_noPersonaFound:true}}];
}
return [{json:{...first.json,synthesis_history:sh}}];

// Merge all downloaded file binaries + add binaryKeys for Anthropic node
const triggerData = $('Execute Workflow Trigger').first().json;
const personaData = $('Ensure Item').first().json;
const downloadedItems = $input.all();

const mergedBinary = {};
const keys = [];
let fileCount = 0;

for (const item of downloadedItems) {
  if (item.binary) {
    for (const [key, value] of Object.entries(item.binary)) {
      const newKey = `file_${fileCount}`;
      mergedBinary[newKey] = value;
      keys.push(newKey);
      fileCount++;
    }
  }
}

return [{
  json: {
    ...personaData,
    sessionId: triggerData.sessionId,
    channelId: triggerData.channelId,
    cleanMessage: triggerData.cleanMessage || '',
    slotNumber: triggerData.slotNumber,
    botName: triggerData.botName,
    fileCount,
    binaryKeys: keys.join(','),
    fileForensic: ($('Get File URL').all() || []).map(function(r,i){var j=r.json||{};return j.extracted_text?'=== Datei '+(i+1)+': '+(j.file_name||'?')+' ===\n'+j.extracted_text:null;}).filter(Boolean).join('\n\n---\n\n')
  },
  binary: fileCount > 0 ? mergedBinary : undefined
}];

// Re-attach binaries from Merge Files + combine with Load Memory results
const mergeItem = $('Merge Files').first();
const memoryItems = $('Load Memory').all();

// Build conversation history
let conversationHistory = 'Kein bisheriges Gespraech';
if (memoryItems.length > 0 && memoryItems[0].json && Object.keys(memoryItems[0].json).length > 0) {
  const history = memoryItems.reverse().map(i => {
    const j = i.json;
    const role = j.role || j.type || 'unknown';
    const content = j.content || j.message || j.text || JSON.stringify(j);
    return role + ': ' + content;
  }).join('\n');
  if (history.trim()) conversationHistory = history;
}

return [{
  json: {
    ...mergeItem.json,
    conversationHistory
  },
  binary: mergeItem.binary || undefined
}];

